class Solution {
public:
    bool canReshape(string& a, string& b) {
        if (a.size() != b.size()) return false;
        vector<int> ca(26, 0), cb(26, 0);
        for (char c : a) ca[c - 'a']++;
        for (char c : b) cb[c - 'a']++;
        for (int x = 0; x < 26; x++) if ((ca[x] > 0) != (cb[x] > 0)) return false;
        sort(ca.begin(), ca.end());
        sort(cb.begin(), cb.end());
        return ca == cb;
    }
};

