static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

bool canReshape(char* a, char* b) {
    if (strlen(a) != strlen(b)) return false;
    int ca[26] = {0}, cb[26] = {0};
    for (; *a; a++) ca[*a - 'a']++;
    for (; *b; b++) cb[*b - 'a']++;
    for (int x = 0; x < 26; x++) if ((ca[x] > 0) != (cb[x] > 0)) return false;
    qsort(ca, 26, sizeof(int), cmp_int);
    qsort(cb, 26, sizeof(int), cmp_int);
    return memcmp(ca, cb, sizeof ca) == 0;
}
